import smtplib

import pytest

import notify
from notify import build_overdue_notice, send_overdue_notice


@pytest.fixture(autouse=True)
def no_smtp(monkeypatch):
    def _boom(*args, **kwargs):
        raise AssertionError("smtplib.SMTP must never be constructed in tests")

    monkeypatch.setattr(smtplib, "SMTP", _boom)


CUSTOMER = {"name": "Ada", "email": "ada@example.org"}


def make_invoice(number, due, cents):
    return {"number": number, "due": due, "cents": cents}


class RecordingMailer:
    def __init__(self):
        self.sent = []

    def send(self, msg):
        self.sent.append(msg)


def test_subject_counts_and_total():
    mailer = RecordingMailer()
    invoices = [
        make_invoice("A-2", "2026-02-01", 2500),
        make_invoice("A-1", "2026-01-01", 1234),
    ]
    send_overdue_notice(CUSTOMER, invoices, mailer)
    assert len(mailer.sent) == 1
    assert mailer.sent[0]["Subject"] == "2 overdue invoice(s), 37.34 EUR"


def test_body_sorted_by_due_date_regardless_of_input_order():
    invoices = [
        make_invoice("B-3", "2026-03-10", 100),
        make_invoice("B-1", "2026-01-05", 300),
        make_invoice("B-2", "2026-02-20", 200),
    ]
    msg = build_overdue_notice(CUSTOMER, invoices)
    body = msg.get_content()
    lines = [ln for ln in body.splitlines() if ln.startswith("- Invoice")]
    numbers = [ln.split()[2] for ln in lines]
    assert numbers == ["B-1", "B-2", "B-3"]


def test_headers_correct():
    msg = build_overdue_notice(CUSTOMER, [make_invoice("C-1", "2026-01-01", 100)])
    assert msg["From"] == "billing@example.com"
    assert msg["To"] == "ada@example.org"


def test_zero_invoices_raises_and_mailer_not_called():
    mailer = RecordingMailer()
    with pytest.raises(ValueError):
        send_overdue_notice(CUSTOMER, [], mailer)
    assert mailer.sent == []


@pytest.mark.parametrize(
    "cents,expected",
    [
        (1234, "12.34"),
        (5, "0.05"),
    ],
)
def test_cents_formatting(cents, expected):
    msg = build_overdue_notice(CUSTOMER, [make_invoice(f"D-{cents}", "2026-01-01", cents)])
    body = msg.get_content()
    line = next(ln for ln in body.splitlines() if ln.startswith("- Invoice"))
    assert f": {expected} EUR" in line


def test_smtp_mailer_wiring_uses_protocol():
    # SmtpMailer satisfies the Mailer protocol and is wired by default helpers.
    assert hasattr(notify.SmtpMailer(), "send")

